import gallery from "./template-gallery.json";
import { appLink } from "./site";

// Generated by scripts/capture-gallery.mjs from the app's starter manifest.
export type GalleryTemplate = (typeof gallery)[number];
export const galleryTemplates: readonly GalleryTemplate[] = gallery;

export const galleryCategories = [
  "Newsletters",
  "Welcome",
  "Product",
  "Commerce",
  "Events",
  "Transactional",
  "Retention",
].filter((c) => gallery.some((t) => t.category === c));

export const getGalleryTemplate = (key: string) =>
  gallery.find((t) => t.key === key);

export const registerHref = appLink("/auth/register?ref=template-gallery");

const whenToUse: Record<string, string> = {
  Newsletters:
    "Use it for a recurring newsletter: a weekly digest, a letter from the editor, or a roundup for people who signed up to hear from you.",
  Welcome:
    "Send it right after someone signs up, as the first email in a welcome or onboarding automation.",
  Product:
    "Use it to announce a release or walk existing users through one new feature.",
  Commerce:
    "Use it for a shop: a new collection, a promotion, or a reminder about something left behind.",
  Events:
    "Use it to invite people to an event, or to remind registrants shortly before it starts.",
  Transactional:
    "Use it for a message someone triggers themselves, such as an order confirmation, a password reset or an address check.",
  Retention:
    "Use it for people who have stopped opening your emails, before you remove them from your list.",
};

// Editorial collection subjects, as they read in a sentence.
const topics: Record<string, string> = {
  places: "travel",
  work: "work and product",
  home: "home and interiors",
};

export function usage(t: GalleryTemplate) {
  const topic =
    t.collection === "Editorial collection"
      ? (topics[t.tags[0]] ?? t.tags[0])
      : undefined;
  return topic
    ? `${whenToUse[t.category]} The sample copy is written for a ${topic} newsletter; swap in your own stories and photos.`
    : whenToUse[t.category];
}
